static char *path_join(const char *directory, const char *name);
static void remove_tree(const char *path);
static int remove_tree_entry(
    const char *path,
    const struct stat *statbuf,
    int typeflag,
    struct FTW *ftwbuf
);
static mylite_open_config open_config(const char *temp_directory, int durability);
static int env_flag(const char *name);
static unsigned env_unsigned(const char *name, unsigned fallback);
static int env_durability(void);
static const char *durability_name(int durability);
static int env_double(const char *name, double *out_value);
static uint64_t monotonic_ns(void);
static double elapsed_seconds(uint64_t start_ns, uint64_t end_ns);
static double average_ms(double seconds, unsigned iterations);
static double operations_per_second(unsigned iterations, double seconds);
static void emit_ms(const char *name, double seconds, unsigned iterations);
static void emit_rate(const char *name, unsigned iterations, double seconds);
static void emit_summary_ms(const char *name, double value);
static void emit_summary_rate(const char *name, double value);
static void emit_summary_ratio(const char *name, double numerator, double denominator);
static void emit_summary_u64(const char *name, uint64_t value);
static void emit_summary_count_per_iteration(const char *name, uint64_t count, unsigned iterations);
static void emit_summary_count_per_iteration_delta(
    const char *name,
    uint64_t left,
    uint64_t right,
    unsigned iterations
);
static void emit_summary_ms_per_iteration(const char *name, uint64_t value_ns, unsigned iterations);
static void emit_summary_ms_per_iteration_delta(
    const char *name,
    uint64_t left_ns,
    uint64_t right_ns,
    unsigned iterations
);
static uint64_t page_publish_sys_identity_space_id(uint64_t identity);
static uint64_t page_publish_sys_identity_page_no(uint64_t identity);
